<script setup lang="ts">
import type { Target } from '../types'
import ImageFallback from './ImageFallback.vue'
defineProps<{ targets:Target[]; history:Target[]; selected:Target|null }>()
const emit=defineEmits<{(e:'select',target:Target):void;(e:'remove',target:Target):void;(e:'restore',target:Target):void}>()
const time=(value?:string)=>value?new Date(value).toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit'}):'暂无'
</script>
<template><aside class="sidebar"><div class="side-heading"><div><span class="eyebrow">COLLECTION</span><h2>监控对象</h2></div><span class="count-pill">{{targets.length+history.length}}</span></div><section><div class="section-label"><span>正在监控</span><b>{{targets.length}}</b></div><div v-for="target in targets" :key="target.id" class="target-card" :class="{selected:selected?.id===target.id}" role="button" tabindex="0" @click="emit('select',target)"><ImageFallback :src="target.cover_url" :kind="target.target_type==='video'?'cover':'avatar'" :alt="target.title"/><div class="target-copy"><strong>{{target.title||target.target_key}}</strong><small>{{target.target_type==='video'?'视频':'UP 主'}} · {{target.target_key}}</small><small class="target-time"><i class="status-dot"></i>{{time(target.last_success_at)}}更新</small></div><button class="target-action icon-button danger-button" title="停止监控" @click.stop="emit('remove',target)">×</button></div></section><section class="history-section"><div class="section-label"><span>历史记录</span><b>{{history.length}}</b></div><div v-for="target in history" :key="'h'+target.id" class="target-card historical" :class="{selected:selected?.id===target.id}" role="button" tabindex="0" @click="emit('select',target)"><ImageFallback :src="target.cover_url" :kind="target.target_type==='video'?'cover':'avatar'" :alt="target.title"/><div class="target-copy"><strong>{{target.title||target.target_key}}</strong><small>{{target.target_type==='video'?'视频':'UP 主'}} · 已停止</small><small class="target-time">{{time(target.last_success_at)}}最后记录</small></div><button class="target-action icon-button soft-button restore" title="恢复监控" @click.stop="emit('restore',target)">↗</button></div><p v-if="!history.length" class="side-empty">暂无历史记录</p></section></aside></template>
